#!/usr/bin/env node
/**
 * Tests for scripts/sweep.mjs: closing the process trees the gate started, listing the other processes that name the
 * work folder, and leaving everything else alone. The process reader and the killer are injected: canned data, no
 * real process is read or closed.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const SCRIPT = join(dirname(fileURLToPath(import.meta.url)), '..', 'scripts', 'sweep.mjs');
const { sweep, render } = await import(pathToFileURL(SCRIPT).href);

const ROOT = '/work/repo';
const SINCE = '2026-01-01T10:00:00.000Z';
const BEFORE = '2026-01-01T09:00:00.000Z';
const DURING = '2026-01-01T10:05:00.000Z';
const LATER = '2026-01-01T10:30:00.000Z';

const proc = (pid, started, cmd = '', ppid = 1) => ({ pid, ppid, name: 'node', started, cmd, path: '' });

/** Runs the sweep over canned processes; `closed` collects the pids the fake killer was asked to close. */
function run({ procs, recorded = [], close = true }) {
  const closed = [];
  const result = sweep({
    root: ROOT, since: SINCE, close, recorded, selfPid: 999999,
    readProcesses: () => procs,
    kill: (pid) => { closed.push(pid); return true; },
  });
  return { result, closed };
}

test('given a live process the gate recorded, when the sweep runs with close, then it is closed and reported closed', () => {
  // Given
  const procs = [proc(100, DURING, 'node server.js')];

  // When
  const { result, closed } = run({ procs, recorded: [{ pid: 100, started: DURING }] });

  // Then
  assert.deepEqual(closed, [100]);
  assert.equal(result.rows.length, 1);
  assert.equal(result.rows[0].owner, 'gate');
  assert.equal(result.rows[0].action, 'closed');
});

test('given a process that names the root and the gate did not record, when the sweep runs with close, then it is listed and left running', () => {
  // Given
  const procs = [proc(200, DURING, `dotnet testhost.dll --root ${ROOT}/bin`)];

  // When
  const { result, closed } = run({ procs });

  // Then
  assert.deepEqual(closed, []);
  assert.equal(result.rows[0].owner, 'unknown');
  assert.equal(result.rows[0].action, 'listed');
});

test('given a recorded pid reused by a newer process, when the sweep runs with close, then it is left running', () => {
  // Given
  const procs = [proc(300, LATER, 'node other.js')];

  // When
  const { result, closed } = run({ procs, recorded: [{ pid: 300, started: DURING }] });

  // Then
  assert.deepEqual(closed, []);
  assert.equal(result.closed, 0);
});

test('given a process started before the run, when the sweep runs, then it is not reported', () => {
  // Given
  const procs = [proc(400, BEFORE, `node watcher.js ${ROOT}`)];

  // When
  const { result, closed } = run({ procs, recorded: [{ pid: 400, started: BEFORE }] });

  // Then
  assert.deepEqual(closed, []);
  assert.deepEqual(result.rows, []);
});

test('given nothing left behind, when the sweep runs, then the last line reports zero closed and zero listed', () => {
  // Given
  const procs = [proc(500, DURING, 'node unrelated.js')];

  // When
  const { result } = run({ procs });

  // Then
  assert.equal(render(result).at(-1), '{"closed":0,"listed":0}');
});
